function drawEquus() {
  var canvas = document.getElementById("myCanvas");
  var ctx = canvas.getContext("2d");

  // Set the canvas dimensions
  canvas.width = 400;
  canvas.height = 400;

  // Draw the body
  ctx.fillStyle = "brown";
  ctx.fillRect(0, 0, canvas.width, canvas.height / 3);

  // Draw the neck
  ctx.fillStyle = "gray";
  ctx.fillRect(0, canvas.height / 3, canvas.width / 2, canvas.height / 3);

  // Draw the head
  ctx.fillStyle = "black";
  ctx.fillRect(0, canvas.height / 3, canvas.width / 2, canvas.height / 3);

  // Draw the legs
  ctx.fillStyle = "black";
  ctx.fillRect(0, canvas.height / 3, canvas.width / 2, canvas.height / 3);
  ctx.fillStyle = "brown";
  ctx.fillRect(0, canvas.height * 2 / 3, canvas.width / 2, canvas.height / 3);
  ctx.fillStyle = "gray";
  ctx.fillRect(0, canvas.height * 2 / 3, canvas.width / 2, canvas.height / 3);

  // Draw the mane
  ctx.fillStyle = "black";
  ctx.beginPath();
  ctx.arc(0, canvas.height / 2, 50, 0, Math.PI * 2);
  ctx.fill();

  // Draw the tail
  ctx.fillStyle = "brown";
  ctx.fillRect(0, canvas.height * 2 / 3, canvas.width, canvas.height / 3);

  // Draw the eyes
  ctx.fillStyle = "black";
  ctx.beginPath();
  ctx.arc(20, canvas.height / 3, 10, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(20, canvas.height * 2 / 3, 10, 0, Math.PI * 2);
  ctx.fill();

  // Draw the ears
  ctx.fillStyle = "black";
  ctx.beginPath();
  ctx.arc(10, canvas.height / 3, 20, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(20, canvas.height / 3, 20, 0, Math.PI * 2);
  ctx.fill();

  // Draw the nostrils
  ctx.fillStyle = "black";
  ctx.beginPath();
  ctx.arc(15, canvas.height / 3, 5, 0, Math.PI * 2);
  ctx.fill();

  // Draw the mouth
  ctx.fillStyle = "black";
  ctx.beginPath();
  ctx.arc(15, canvas.height * 2 / 3, 10, 0, Math.PI * 2);
  ctx.fill();

  // Draw the hooves
  ctx.fillStyle = "brown";
  ctx.beginPath();
  ctx.arc(0, canvas.height * 2 / 3, 10, 0, Math.PI * 2);
  ctx.fill();

  // Add some texture to the body
  ctx.fillStyle = "brown";
  ctx.beginPath();
  ctx.rect(0, canvas.height * 2 / 3, 10, canvas.height / 3);
  ctx.fill();

  // Add some texture to the mane
  ctx.fillStyle = "black";
  ctx.beginPath();
  ctx.arc(0, canvas.height / 2, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(0, canvas.height * 2 / 3, 5, 0, Math.PI * 2);
  ctx.fill();

  // Add some texture to the tail
  ctx.fillStyle = "brown";
  ctx.beginPath();
  ctx.rect(0, canvas.height * 2 / 3, 10, canvas.height / 3);
  ctx.fill();
}

// Call the function to draw the equus
drawEquus();
```
